  }
  final EventChannel playerEventsChannel = EventChannel(
    'dev.flutter.pigeon.reelkit_ios.ReelKitEventApi.playerEvents$instanceName',
    pigeonMethodCodec,
  );
  return playerEventsChannel.receiveBroadcastStream().map((dynamic event) {
    return event as PlatformPlayerEvent;
  });
}
